''' Formats the data for the tree accounting for expanded state and filter '''

userFilter = value.get("filter")
productionModel = value.get("productionModel")
filterChanged = self.custom.data.filterChanged
expandedTree = self.custom.data.expandedTree if self.custom.data.expandedTree not in ['', None, []] and not filterChanged else False
self.custom.data.filterChanged = False
if not productionModel:
	return []
# --- Loops through each asset type to determine if matched and also grabs the last expanded state from the expandedTree ---
filteredTree = []
# - Loops through the enterprise assets
test = []
eNeedsExpanded = False
for eIndex, enterprise in enumerate(productionModel):
	eData = enterprise.get("data")
	eLabel = eData.get("assetName")
	eMatch = userFilter.lower() in eLabel.lower() if userFilter else True
	# - Sets the expanded property to the last expanded state or initializes to false
	if expandedTree:
		eLengthGood = True if eIndex < len(expandedTree) else False
		eExpanded = expandedTree[eIndex]["expanded"] if eLengthGood else False
	else:
		eExpanded = False

	eTree = {
		"label": eLabel,
		"data": eData,
		"icon": {
			"path": "material/business",
			"color": "",
			"style": {}
		},
		"expanded": eExpanded,
		"items": []
	}

	# - Loops through the site assets
	sNeedsExpanded = False
	for sIndex, site in enumerate(enterprise.get("items", [])):
		sData = site.get("data")
		sLabel = sData.get("assetName")
		sMatch = userFilter.lower() in sLabel.lower() if userFilter else True
		if sMatch:
			eNeedsExpanded = True
		else: pass			
		# - Sets the expanded property to the last expanded state or initializes to false
		if expandedTree:
			sLengthGood = True if sIndex < len(expandedTree[eIndex]["items"]) else False
			sExpanded = expandedTree[eIndex]["items"][sIndex]["expanded"] if eLengthGood and sLengthGood else False
		else:
			sExpanded = False

		sTree = {
			"label": sLabel,
			"data": sData,
			"icon": {
				"path": "material/location_city",
				"color": "",
				"style": {}
			},
			"expanded": sExpanded,
			"items": []
		}

		# - Loops through the area assets
		aNeedsExpanded = False
		for aIndex, area in enumerate(site.get("items", [])):
			aData = area.get("data")
			aLabel = aData.get("assetName")
			aMatch = userFilter.lower() in aLabel.lower() if userFilter else True
			if aMatch:
				sNeedsExpanded = True
			else: pass
			# - Sets the expanded property to the last expanded state or initializes to false
			if expandedTree:
				aLengthGood = True if aIndex < len(expandedTree[eIndex]["items"][sIndex]["items"]) else False
				aExpanded = expandedTree[eIndex]["items"][sIndex]["items"][aIndex]["expanded"] if eLengthGood and sLengthGood and aLengthGood else False
			else:
				aExpanded = False

			aTree = {
				"label": aLabel,
				"data": aData,
				"icon": {
					"path": "material/business_center",
					"color": "",
					"style": {}
				},
				"expanded": aExpanded,
				"items": []
			}

			# - Loops through the line assets
			lNeedsExpanded = False
			for lIndex, line in enumerate(area.get("items", [])):
				lData = line.get("data")
				lLabel = lData.get("assetName")
				lMatch = userFilter.lower() in lLabel.lower() if userFilter else True
				if lMatch:
					aNeedsExpanded = True
				else: pass
				# - Sets the expanded property to the last expanded state or initializes to false
				if expandedTree:
					lLengthGood = True if lIndex < len(expandedTree[eIndex]["items"][sIndex]["items"][aIndex]["items"]) else False
					lExpanded = expandedTree[eIndex]["items"][sIndex]["items"][aIndex]["items"][lIndex]["expanded"] if eLengthGood and sLengthGood and aLengthGood and lLengthGood else False
				else:
					lExpanded = False

				lTree = {
					"label": lLabel,
					"data": lData,
					"icon": {
						"path": "material/line_style",
						"color": "",
						"style": {}
					},
					"expanded": lExpanded,
					"items": []
				}

				# - Loops through the cell and cell group assets
				for cIndex, cell in enumerate(line.get("items", [])):
					cData = cell.get("data")
					cLabel = cData.get("assetName")
					cMatch = userFilter.lower() in cLabel.lower() if userFilter else True
					if cMatch:
						lNeedsExpanded = True
					else: pass
					cExpanded = False

					# - Appends the asset tree dict when a filter has not been entered, matches the filter, or has a parent that matches the filter
					if not userFilter or cMatch or lMatch or aMatch or sMatch or eMatch:
						iconPath = "material/fact_check" if cell["data"]["assetType"] == "group" else "material/settings_cell"

						lTree["items"].append({
							"label": cLabel,
							"data": cData,
							"icon": {
								"path": iconPath,
								"color": "",
								"style": {}
							},
							"expanded": cExpanded,
							"items": []
						})

				# - Appends the asset tree dict when a filter has not been entered, matches the filter, or has a child that matches the filter
				# - Also, updates the expanded property if there is a filter enetered
				lTree["expanded"] = True if userFilter and lNeedsExpanded else False
				if not userFilter or lMatch or lTree["items"]:
					aTree["items"].append(lTree)
			aTree["expanded"] = True if userFilter and (aNeedsExpanded or lNeedsExpanded) else False
			if not userFilter or aMatch or aTree["items"]:
				sTree["items"].append(aTree)
		sTree["expanded"] = True if userFilter and (sNeedsExpanded or aNeedsExpanded or lNeedsExpanded) else False
		if not userFilter or sMatch or sTree["items"]:
			eTree["items"].append(sTree)
	eTree["expanded"] = True if userFilter and (eNeedsExpanded or sNeedsExpanded or aNeedsExpanded or lNeedsExpanded) else False
	if not userFilter or eMatch or eTree["items"]:
		filteredTree.append(eTree)

return filteredTree

''' Gets the tabs based on the the tree selection '''

if value == '':
	return []
else:
	assetType = value.get('EqType')
	assetType = assetType.lower()
	if assetType in ['enterprise', 'site', 'area']:
		tabs = ['Mapping']
	elif assetType == 'line':
		tabs = ['Mapping', 'Line States', 'Alert Thresholds']
	elif assetType == 'group':
		tabs = ['Mapping', 'Alert Thresholds']
	else:
		tabs = ['Mapping', 'Cell States', 'Alert Thresholds']

return tabs

